import {hospitalById} from './request-utils.js';
import {resources} from './seed.js';
const params=new URLSearchParams(location.search),id=params.get('id'),h=hospitalById(id);
const role=params.get('role')==='hospital'?'hospital':'ems',base=hospitalById(params.get('hospital'))?.id||'cedar';
const radius=Number(params.get('radius')),back=new URLSearchParams({hospital:base,role,selected:h?.id||base,radius:String(Number.isInteger(radius)&&radius>=1&&radius<=2000?radius:100),resource:resources.includes(params.get('resource'))?params.get('resource'):'All resources',tiles:params.get('tiles')==='off'?'off':'on'});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const root=document.querySelector('#profile');
if(!h){root.innerHTML='<h1>Hospital not found</h1><p>Choose a hospital from the BC map.</p><a href="/network.html">Open BC map</a>';}
else{
 root.innerHTML=`<header class="core-header"><a class="core-brand" href="/?role=${role}&hospital=${base}"><img class="brand-logo" data-testid="brand-logo" src="/logo.svg" alt="Hospital Connect logo"><span class="brand-copy">Hospital Connect<small>Hospital profile</small></span></a><a class="secondary" data-testid="profile-back-map" href="/network.html?${esc(back)}">← Back to BC map</a><a class="secondary" data-testid="open-about" href="/about.html?role=${role}&hospital=${base}">About Us</a></header><div class="core-banner"><strong>Prototype disclaimer.</strong> Shared public access; desk selectors are not sign-in. Hospital locations and capacity are invented. Do not enter patient information. Confirm capacity directly before any real transfer. Notifications stay in this app; no emergency dispatch, email or SMS is sent.</div><section class="panel hospital-profile" data-testid="hospital-profile"><div class="section-kicker">HOSPITAL PROFILE</div><h1>${esc(h.name)}</h1><p>${esc(h.town)} · ${h.lat.toFixed(4)}°, ${h.lng.toFixed(4)}°</p><div id="profile-status" role="status">Checking availability…</div><h2>Resources</h2><div class="profile-resources">${h.resources.map(r=>`<span class="tag">${esc(r)}</span>`).join('')}</div><h2>Coordination contact</h2><p>${esc(h.contact)}</p><p class="muted">This profile is for exploring one hospital. Opening its working desk is a separate action.</p><div class="buttonrow"><a class="primary" data-testid="profile-open-desk" href="/?role=hospital&hospital=${h.id}">Open ${esc(h.short)} hospital desk</a><a class="secondary" data-testid="profile-return-desk" href="/?role=${role}&hospital=${base}">Return to your ${role==='ems'?'EMS':'hospital'} desk</a></div></section>`;
 let loading=false;
 async function refresh(){if(loading)return;loading=true;try{const r=await fetch('/api/readiness');if(!r.ok)throw Error();const data=await r.json(),facility=data.facilities.find(x=>x.id===h.id);if(!facility)throw Error();document.querySelector('#profile-status').innerHTML=`<span class="tag ${facility.state==='Closed'?'critical':facility.state==='Limited'?'warning':''}" data-testid="profile-availability">${esc(facility.state)}</span><p class="compact-meta">Last updated: ${facility.updatedAt?esc(new Date(facility.updatedAt).toLocaleString()):'Not yet updated'}</p>`;}catch{document.querySelector('#profile-status').textContent='Availability unavailable. Refresh this page to retry; do not rely on an earlier status.';}finally{loading=false;}}
 refresh();setInterval(()=>{if(!document.hidden)refresh();},4000);
}
